begin;
with j as (select * from jsonb_to_recordset($law7d0039$[{"code_id":"GK_RF_2","article_number":"952","version_date":"1994-11-30","article_text":"1. Имущество и предпринимательский риск могут быть застрахованы от разных страховых рисков как по одному, так и по отдельным договорам страхования, в том числе по договорам с разными страховщиками.\n\nВ этих случаях допускается превышение размера общей страховой суммы по всем договорам над страховой стоимостью.\n\n2. Если из двух или нескольких договоров, заключенных в соответствии с пунктом 1 настоящей статьи, вытекает обязанность страховщиков выплатить страховое возмещение за одни и те же последствия наступления одного и того же страхового случая, к таким договорам в соответствующей части применяются правила, предусмотренные пунктом 4 статьи 951 настоящего Кодекса.","article_title":"Статья 952. Имущественное страхование от разных страховых рисков","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8a2cce6d925ec92160f73c4f8275854b7ffa5921fa5ca6d295a63c76ab00acde"},{"code_id":"GK_RF_2","article_number":"953","version_date":"1994-11-30","article_text":"Объект страхования может быть застрахован по одному договору страхования совместно несколькими страховщиками (сострахование). Если в таком договоре не определены права и обязанности каждого из страховщиков, они солидарно отвечают перед страхователем (выгодоприобретателем) за выплату страхового возмещения по договору имущественного страхования или страховой суммы по договору личного страхования.","article_title":"Статья 953. Сострахование","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f6b0d07efd9b8dd7875ac51f500ca70d25e40f280f69eefe38ffb0331c4bf268"},{"code_id":"GK_RF_2","article_number":"954","version_date":"1994-11-30","article_text":"1. Под страховой премией понимается плата за страхование, которую страхователь (выгодоприобретатель) обязан уплатить страховщику в порядке и в сроки, которые установлены договором страхования.\n\n2. Страховщик при определении размера страховой премии, подлежащей уплате по договору страхования, вправе применять разработанные им страховые тарифы, определяющие премию, взимаемую с единицы страховой суммы, с учетом объекта страхования и характера страхового риска.\n\nВ предусмотренных законом случаях размер страховой премии определяется в соответствии со страховыми тарифами, установленными или регулируемыми органами страхового надзора. (В редакции Федерального закона от 23.07.2013 № 251-ФЗ)\n\n3. Если договором страхования предусмотрено внесение страховой премии в рассрочку, договором могут быть определены последствия неуплаты в установленные сроки очередных страховых взносов.\n\n4. Если страховой случай наступи\n\nл до уплаты очередного страхового взноса, внесение которого просрочено, страховщик вправе при определении размера подлежащего выплате страхового возмещения по договору имущественного страхования или страховой суммы по договору личного страхования зачесть сумму просроченного страхового взноса.","article_title":"Статья 954. Страховая премия и страховые взносы","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"45efc8f5877a152eb073fa38a5fca0f8af676aafdd4998ecd523cd3246e780cb"},{"code_id":"GK_RF_2","article_number":"955","version_date":"1994-11-30","article_text":"1. В случае, когда по договору страхования риска ответственности за причинение вреда (статья 931) застрахована ответственность лица иного, чем страхователь, последний вправе, если иное не предусмотрено договором, в любое время до наступления страхового случая заменить это лицо другим, письменно уведомив об этом страховщика.\n\n2. Застрахованное лицо, названное в договоре личного страхования, может быть заменено страхователем другим лицом лишь с согласия самого застрахованного лица и страховщика.","article_title":"Статья 955. Замена застрахованного лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"65f5426713bf87d32f4c6e010b2a8a865891439a75577ee97fd2687a97b08433"},{"code_id":"GK_RF_2","article_number":"956","version_date":"1994-11-30","article_text":"Страхователь вправе заменить выгодоприобретателя, названного в договоре страхования, другим лицом, письменно уведомив об этом страховщика. Замена выгодоприобретателя по договору личного страхования, назначенного с согласия застрахованного лица (пункт 2 статьи 934), допускается лишь с согласия этого лица.\n\nВыгодоприобретатель не может быть заменен другим лицом после того, как он выполнил какую-либо из обязанностей по договору страхования или предъявил страховщику требование о выплате страхового возмещения или страховой суммы.","article_title":"Статья 956. Замена выгодоприобретателя","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"31eb31bc74b5559e6ebfff63c2f9aff0e627239a9424bbdd68025dcacd4fe7c5"},{"code_id":"GK_RF_2","article_number":"957","version_date":"1994-11-30","article_text":"1. Договор страхования, если в нем не предусмотрено иное, вступает в силу в момент уплаты страховой премии или первого ее взноса.\n\n2. Страхование, обусловленное договором страхования, распространяется на страховые случаи, происшедшие после вступления договора страхования в силу, если в договоре не предусмотрен иной срок начала действия страхования.","article_title":"Статья 957. Начало действия договора страхования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ee790e110d03fa33c7d2305f67183f784ef949729ac86d33cd214aa806601ec3"},{"code_id":"GK_RF_2","article_number":"958","version_date":"1994-11-30","article_text":"1. Договор страхования прекращается до наступления срока, на который он был заключен, если после его вступления в силу возможность наступления страхового случая отпала и существование страхового риска прекратилось по обстоятельствам иным, чем страховой случай. К таким обстоятельствам, в частности, относятся:\n\nгибель застрахованного имущества по причинам иным, чем наступление страхового случая;\n\nпрекращение в установленном порядке предпринимательской деятельности лицом, застраховавшим предпринимательский риск или риск гражданской ответственности, связанной с этой деятельностью.\n\n2. Страхователь (выгодоприобретатель) вправе отказаться от договора страхования в любое время, если к моменту отказа возможность наступления страхового случая не отпала по обстоятельствам, указанным в пункте 1 настоящей статьи.\n\n3. При досрочном прекращении договора страхования по обстоятельствам, указанным в пункте 1 настоящей статьи, страховщик имеет право на часть страховой премии пропорционально времени, в течение которого действовало страхование.\n\nПри досрочном отказе страхователя (выгодоприобретателя) от договора страхования уплаченная страховщику страховая премия не подлежит возврату, если законом или договором не предусмотрено иное. (В редакции Федерального закона от 27.12.2019 № 489-ФЗ)","article_title":"Статья 958. Досрочное прекращение договора страхования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0d0c673ad7eab0fb80b4939289107e6f0aca275f91ae28d3aedf49b86bac423d"},{"code_id":"GK_RF_2","article_number":"959","version_date":"1994-11-30","article_text":"1. В период действия договора имущественного страхования страхователь (выгодоприобретатель) обязан незамедлительно сообщать страховщику о ставших ему известными значительных изменениях в обстоятельствах, сообщенных страховщику при заключении договора, если эти изменения могут существенно повлиять на увеличение страхового риска.\n\nЗначительными во всяком случае признаются изменения, оговоренные в договоре страхования (страховом полисе) и в переданных страхователю правилах страхования.\n\n2. Страховщик, уведомленный об обстоятельствах, влекущих увеличение страхового риска, вправе потребовать изменения условий договора страхования или уплаты дополнительной страховой премии соразмерно увеличению риска.\n\nЕсли страхователь (выгодоприобретатель) возражает против изменения условий договора страхования или доплаты страховой премии, страховщик вправе потребовать расторжения договора в соответствии с правилами, предусмотренными главой 29 настоящего Кодекса.\n\n3. При неисполнении страхователем либо выгодоприобретателем предусмотренной в пункте 1 настоящей статьи обязанности страховщик вправе потребовать расторжения договора страхования и возмещения убытков, причиненных расторжением договора (пункт 5 статьи 453).\n\n4. Страховщик не вправе требовать расторжения договора страхования, если обстоятельства, влекущие увеличение страхового риска, уже отпали.\n\n5. При личном страховании последствия изменения страхового риска в период действия договора страхования, указанные в пунктах 2 и 3 настоящей статьи, могут наступить, только если они прямо предусмотрены в договоре.","article_title":"Статья 959. Последствия увеличения страхового риска в период действия договора страхования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ade9339876e486113093576b376dd47eeff662ceb0b6bacb3ceda3151f213917"},{"code_id":"GK_RF_2","article_number":"960","version_date":"1994-11-30","article_text":"При переходе прав на застрахованное имущество от лица, в интересах которого был заключен договор страхования, к другому лицу права и обязанности по этому договору переходят к лицу, к которому перешли права на имущество, за исключением случаев принудительного изъятия имущества по основаниям, указанным в пункте 2 статьи 235 настоящего Кодекса, и отказа от права собственности (статья 236).\n\nЛицо, к которому перешли права на застрахованное имущество, должно незамедлительно письменно уведомить об этом страховщика.","article_title":"Статья 960. Переход прав на застрахованное имущество к другому лицу","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a3e46a9f511a0f7ea7633da7554fd3e083d0d106a5a330461f5f1212e8720033"},{"code_id":"GK_RF_2","article_number":"961","version_date":"1994-11-30","article_text":"1. Страхователь по договору имущественного страхования после того, как ему стало известно о наступлении страхового случая, обязан незамедлительно уведомить о его наступлении страховщика или его представителя. Если договором предусмотрен срок и (или) способ уведомления, оно должно быть сделано в условленный срок и указанным в договоре способом.\n\nТакая же обязанность лежит на выгодоприобретателе, которому известно о заключении договора страхования в его пользу, если он намерен воспользоваться правом на страховое возмещение.\n\n2. Неисполнение обязанности, предусмотренной пунктом 1 настоящей статьи, дает страховщику право отказать в выплате страхового возмещения, если не будет доказано, что страховщик своевременно узнал о наступлении страхового случая либо что отсутствие у страховщика сведений об этом не могло сказаться на его обязанности выплатить страховое возмещение.\n\n3. Правила, предусмотренные пунктами 1 и 2 настоящей статьи, соответственно применяются к договору личного страхования, если страховым случаем является смерть застрахованного лица или причинение вреда его здоровью. При этом устанавливаемый договором срок уведомления страховщика не может быть менее тридцати дней.","article_title":"Статья 961. Уведомление страховщика о наступлении страхового случая","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e7a9c4ebe683e57590f96925ad79ab0c617a7e1b4a9df617f1b4e9b5ff665e68"},{"code_id":"GK_RF_2","article_number":"962","version_date":"1994-11-30","article_text":"1. При наступлении страхового случая, предусмотренного договором имущественного страхования, страхователь обязан принять разумные и доступные в сложившихся обстоятельствах меры, чтобы уменьшить возможные убытки.\n\nПринимая такие меры, страхователь должен следовать указаниям страховщика, если они сообщены страхователю.\n\n2. Расходы в целях уменьшения убытков, подлежащих возмещению страховщиком, если такие расходы были необходимы или были произведены для выполнения указаний страховщика, должны быть возмещены страховщиком, даже если соответствующие меры оказались безуспешными.\n\nТакие расходы возмещаются пропорционально отношению страховой суммы к страховой стоимости независимо от того, что вместе с возмещением других убытков они могут превысить страховую сумму.\n\n3. Страховщик освобождается от возмещения убытков, возникших вследствие того, что страхователь умышленно не принял разумных и доступных ему мер, чтобы уменьшить возможные убытки.","article_title":"Статья 962. Уменьшение убытков от страхового случая","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"93526d8e73228e37d0e44b1343f95d99f3479fc2218e77f95582fd1e0154f92c"},{"code_id":"GK_RF_2","article_number":"963","version_date":"1994-11-30","article_text":"1. Страховщик освобождается от выплаты страхового возмещения или страховой суммы, если страховой случай наступил вследствие умысла страхователя, выгодоприобретателя или застрахованного лица, за исключением случаев, предусмотренных пунктами 2 и 3 настоящей статьи.\n\nЗаконом могут быть предусмотрены случаи освобождения страховщика от выплаты страхового возмещения по договорам имущественного страхования при наступлении страхового случая вследствие грубой неосторожности страхователя или выгодоприобретателя.\n\n2. Страховщик не освобождается от выплаты страхового возмещения по договору страхования гражданской ответственности за причинение вреда жизни или здоровью, если вред причинен по вине ответственного за него лица.\n\n3. Страховщик не освобождается от выплаты страховой суммы, которая по договору личного страхования подлежит выплате в случае смерти застрахованного лица, если его смерть наступила вследствие самоубийства и к этому времени договор страхования действовал уже не менее двух лет.","article_title":"Статья 963. Последствия наступления страхового случая по вине страхователя, выгодоприобретателя или застрахованного лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b7d4adc6e7adc63ddda50f27949a028e03da5852f7ddc3ed5f0fa8f174b233f2"},{"code_id":"GK_RF_2","article_number":"964","version_date":"1994-11-30","article_text":"1. Если законом или договором страхования не предусмотрено иное, страховщик освобождается от выплаты страхового возмещения и страховой суммы, когда страховой случай наступил вследствие:\n\nвоздействия ядерного взрыва, радиации или радиоактивного заражения;\n\nвоенных действий, а также маневров или иных военных мероприятий;\n\nгражданской войны, народных волнений всякого рода или забастовок.\n\n2. Если договором имущественного страхования не предусмотрено иное, страховщик освобождается от выплаты страхового возмещения за убытки, возникшие вследствие изъятия, конфискации, реквизиции, ареста или уничтожения застрахованного имущества по распоряжению государственных органов.","article_title":"Статья 964. Основания освобождения страховщика от выплаты страхового возмещения и страховой суммы","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"50b0f58f273986a53c4438792d9a8b9a14a92cc6f62045b4ee048df5272ed2c1"},{"code_id":"GK_RF_2","article_number":"965","version_date":"1994-11-30","article_text":"1. Если договором имущественного страхования не предусмотрено иное, к страховщику, выплатившему страховое возмещение, переходит в пределах выплаченной суммы право требования, которое страхователь (выгодоприобретатель) имеет к лицу, ответственному за убытки, возмещенные в результате страхования. Однако условие договора, исключающее переход к страховщику права требования к лицу, умышленно причинившему убытки, ничтожно.\n\n2. Перешедшее к страховщику право требования осуществляется им с соблюдением правил, регулирующих отношения между страхователем (выгодоприобретателем) и лицом, ответственным за убытки.\n\n3. Страхователь (выгодоприобретатель) обязан передать страховщику все документы и доказательства и сообщить ему все сведения, необходимые для осуществления страховщиком перешедшего к нему права требования.\n\n4. Если страхователь (выгодоприобретатель) отказался от своего права требования к лицу, ответственному за убытки, возмещенные страховщиком, или осуществление этого права стало невозможным по вине страхователя (выгодоприобретателя), страховщик освобождается от выплаты страхового возмещения полностью или в соответствующей части и вправе потребовать возврата излишне выплаченной суммы возмещения.","article_title":"Статья 965. Переход к страховщику прав страхователя на возмещение ущерба (суброгация)","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"aca4e6ded70959d14535bb48bb2bfced5427cf2e38d83cf5d5b15a1d3b035116"},{"code_id":"GK_RF_2","article_number":"966","version_date":"1994-11-30","article_text":"1. Срок исковой давности по требованиям, вытекающим из договора имущественного страхования, за исключением договора страхования риска ответственности по обязательствам, возникающим вследствие причинения вреда жизни, здоровью или имуществу других лиц, составляет два года.\n\n2. Срок исковой давности по требованиям, вытекающим из договора страхования риска ответственности по обязательствам, возникающим вследствие причинения вреда жизни, здоровью или имуществу других лиц, составляет три года (статья 196).\n\n(Статья в редакции Федерального закона от 04.11.2007 № 251-ФЗ)","article_title":"Статья 966. Исковая давность по требованиям, связанным с имущественным страхованием","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"88e1e2dff87af11b24894e7beb7c8a1b41382ab51f36d4fbc1e940a6dfac5558"},{"code_id":"GK_RF_2","article_number":"967","version_date":"1994-11-30","article_text":"1. Риск выплаты страхового возмещения или страховой суммы, принятый на себя страховщиком по договору страхования, может быть им застрахован полностью или частично у другого страховщика (страховщиков) по заключенному с последним договору перестрахования.\n\n2. К договору перестрахования применяются правила, предусмотренные настоящей главой, подлежащие применению в отношении страхования предпринимательского риска, если договором перестрахования не предусмотрено иное. При этом страховщик по договору страхования (основному договору), заключивший договор перестрахования, считается в этом последнем договоре страхователем.\n\n3. При перестраховании ответственным перед страхователем по основному договору страхования за выплату страхового возмещения или страховой суммы остается страховщик по этому договору.\n\n4. Допускается последовательное заключение двух или нескольких договоров перестрахования.","article_title":"Статья 967. Перестрахование","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a1bfae1f9b4bd20e8e92bd8f467dc4aec0251c761d6d9e389d52f53f7ef66837"},{"code_id":"GK_RF_2","article_number":"968","version_date":"1994-11-30","article_text":"1. Граждане и юридические лица могут страховать свое имущество и иные имущественные интересы, указанные в пункте 2 статьи 929 настоящего Кодекса, на взаимной основе путем объединения в обществах взаимного страхования необходимых для этого средств.\n\n2. Общества взаимного страхования осуществляют страхование имущества и иных имущественных интересов своих членов и являются некоммерческими организациями.\n\nОсобенности правового положения обществ взаимного страхования и условия их деятельности определяются в соответствии с настоящим Кодексом законом о взаимном страховании.\n\nПравила, предусмотренные настоящей главой, применяются к отношениям по страхованию между обществом взаимного страхования и его членами, если иное не предусмотрено законом о взаимном страховании. (В редакции Федерального закона от 29.11.2007 № 287-ФЗ)","article_title":"Статья 968. Взаимное страхование","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"36665d4530a1c98c765fe08d73ffcc6062a36ef8a71d9cccda9967c5ddda8993"},{"code_id":"GK_RF_2","article_number":"969","version_date":"1994-11-30","article_text":"1. В целях обеспечения социальных интересов граждан и интересов государства законом может быть установлено обязательное государственное страхование жизни, здоровья и имущества государственных служащих определенных категорий.\n\nОбязательное государственное страхование осуществляется за счет средств, выделяемых на эти цели из соответствующего бюджета министерствам и иным федеральным органам исполнительной власти (страхователям).\n\n2. Обязательное государственное страхование осуществляется непосредственно на основании законов и иных правовых актов о таком страховании указанными в этих актах государственными страховыми или иными государственными организациями (страховщиками) либо на основании договоров страхования, заключаемых в соответствии с этими актами страховщиками и страхователями.\n\n3. Обязательное государственное страхование оплачивается страховщикам в размере, определенном законами и иными правовыми актами о таком страховании.\n\n4. Правила, предусмотренные настоящей главой, применяются к обязательному государственному страхованию, если иное не предусмотрено законами и иными правовыми актами о таком страховании и не вытекает из существа соответствующих отношений по страхованию.","article_title":"Статья 969. Обязательное государственное страхование","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0d0dc928653c8c1281417bdcb56cc6bfbae73558d7ebfc54282e30f2c9406c4f"},{"code_id":"GK_RF_2","article_number":"970","version_date":"1994-11-30","article_text":"Правила, предусмотренные настоящей главой, применяются к отношениям по страхованию иностранных инвестиций от некоммерческих рисков, морскому страхованию, медицинскому страхованию, страхованию банковских вкладов, страхованию пенсий и страхованию экспортных кредитов и инвестиций от предпринимательских и (или) политических рисков постольку, поскольку законами об этих видах страхования и Федеральным законом от 17 мая 2007 года № 82-ФЗ \"О банке развития\" не установлено иное. (В редакции Федерального закона от 29.06.2015 № 185-ФЗ)","article_title":"Статья 970. Применение общих правил о страховании к специальным видам страхования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2143754e565af9f65861e1413b36debfce474a0f6fdba5cdd2e424da4dc957ff"},{"code_id":"GK_RF_2","article_number":"971","version_date":"1994-11-30","article_text":"1. По договору поручения одна сторона (поверенный) обязуется совершить от имени и за счет другой стороны (доверителя) определенные юридические действия. Права и обязанности по сделке, совершенной поверенным, возникают непосредственно у доверителя.\n\n2. Договор поручения может быть заключен с указанием срока, в течение которого поверенный вправе действовать от имени доверителя, или без такого указания.","article_title":"Статья 971. Договор поручения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8ae2d403bd8731015a019ee4d6e54ec1e78dae0649b5ae156c5413214903787d"},{"code_id":"GK_RF_2","article_number":"972","version_date":"1994-11-30","article_text":"1. Доверитель обязан уплатить поверенному вознаграждение, если это предусмотрено законом, иными правовыми актами или договором поручения.\n\nВ случаях, когда договор поручения связан с осуществлением обеими сторонами или одной из них предпринимательской деятельности, доверитель обязан уплатить поверенному вознаграждение, если договором не предусмотрено иное.\n\n2. При отсутствии в возмездном договоре поручения условия о размере вознаграждения или о порядке его уплаты вознаграждение уплачивается после исполнения поручения в размере, определяемом в соответствии с пунктом 3 статьи 424 настоящего Кодекса.\n\n3. Поверенный, действующий в качестве коммерческого представителя (пункт 1 статьи 184), вправе в соответствии со статьей 359 настоящего Кодекса удерживать находящиеся у него вещи, которые подлежат передаче доверителю, в обеспечение своих требований по договору поручения.","article_title":"Статья 972. Вознаграждение поверенного","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"be73bac00f56cc9e2f055224b6c29d44984f070e030f5af2852da0fd9945b2c6"},{"code_id":"GK_RF_2","article_number":"973","version_date":"1994-11-30","article_text":"1. Поверенный обязан исполнять данное ему поручение в соответствии с указаниями доверителя. Указания доверителя должны быть правомерными, осуществимыми и конкретными.\n\n2. Поверенный вправе отступить от указаний доверителя, если по обстоятельствам дела это необходимо в интересах доверителя и поверенный не мог предварительно запросить доверителя либо не получил в разумный срок ответа на свой запрос. Поверенный обязан уведомить доверителя о допущенных отступлениях, как только уведомление стало возможным.\n\n3. Поверенному, действующему в качестве коммерческого представителя (пункт 1 статьи 184), может быть предоставлено доверителем право отступать в интересах доверителя от его указаний без предварительного запроса об этом. В этом случае коммерческий представитель обязан в разумный срок уведомить доверителя о допущенных отступлениях, если иное не предусмотрено договором поручения.","article_title":"Статья 973. Исполнение поручения в соответствии с указаниями доверителя","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9004b28d1ebf1bc3bc20670895acb2ae89841c92e3ddfcc606f4af2ce472596a"},{"code_id":"GK_RF_2","article_number":"974","version_date":"1994-11-30","article_text":"Поверенный обязан:\n\nлично исполнять данное ему поручение, за исключением случаев, указанных в статье 976 настоящего Кодекса;\n\nсообщать доверителю по его требованию все сведения о ходе исполнения поручения;\n\nпередавать доверителю без промедления все полученное по сделкам, совершенным во исполнение поручения;\n\nпо исполнении поручения или при прекращении договора поручения до его исполнения без промедления возвратить доверителю доверенность, срок действия которой не истек, и представить отчет с приложением оправдательных документов, если это требуется по условиям договора или характеру поручения.","article_title":"Статья 974. Обязанности поверенного","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"229298dedb7dd34506b6ec37dd543a3f2a9437c58f7c77623f17b43266936478"},{"code_id":"GK_RF_2","article_number":"975","version_date":"1994-11-30","article_text":"1. Доверитель обязан выдать поверенному доверенность (доверенности) на совершение юридических действий, предусмотренных договором поручения, за исключением случаев, предусмотренных абзацем вторым пункта 1 статьи 182 настоящего Кодекса.\n\n2. Доверитель обязан, если иное не предусмотрено договором:\n\nвозмещать поверенному понесенные издержки;\n\nобеспечивать поверенного средствами, необходимыми для исполнения поручения.\n\n3. Доверитель обязан без\n\nпромедления принять от поверенного все исполненное им в соответствии с договором поручения.\n\n4. Доверитель обязан уплатить поверенному вознаграждение, если в соответствии со статьей 972 настоящего Кодекса договор поручения является возмездным.","article_title":"Статья 975. Обязанности доверителя","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6a408db4968d480e96c920e3e2294ad349fe91230bddaf467ed72ca23d8e5fb7"},{"code_id":"GK_RF_2","article_number":"976","version_date":"1994-11-30","article_text":"1. Поверенный вправе передать исполнение поручения другому лицу (заместителю) лишь в случаях и на условиях, предусмотренных статьей 187 настоящего Кодекса.\n\n2. Доверитель вправе отвести заместителя, избранного поверенным.\n\n3. Если возможный заместитель поверенного поименован в договоре поручения, поверенный не отвечает ни за его выбор, ни за ведение им дел.\n\nЕсли право поверенного передать исполнение поручения другому лицу в договоре не предусмотрено либо предусмотрено, но заместитель в нем не поименован, поверенный отвечает за выбор заместителя.","article_title":"Статья 976. Передоверие исполнения поручения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"590784e5037c0d70e4a0d74f890689738c7444241bf8c358e2820e8d1f101ccc"},{"code_id":"GK_RF_2","article_number":"977","version_date":"1994-11-30","article_text":"1. Договор поручения прекращается вследствие:\n\nотмены поручения доверителем;\n\nотказа поверенного;\n\nсмерти доверителя или поверенного, признания кого-либо из них недееспособным, ограниченно дееспособным или безвестно отсутствующим.\n\n2. Доверитель вправе отменить поручение, а поверенный отказаться от него во всякое время. Соглашение об отказе от этого права ничтожно.\n\n3. Сторона, отказывающаяся от договора поручения, предусматривающего действия поверенного в качестве коммерческого представителя, должна уведомить другую сторону о прекращении договора не позднее чем за тридцать дней, если договором не предусмотрен более длительный срок.\n\nПри реорганизации юридического лица, являющегося коммерческим представителем, доверитель вправе отменить поручение без такого предварительного уведомления.","article_title":"Статья 977. Прекращение договора поручения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5e3bcaed8af2ad177af943c880d08a8fd6c70f977317d37b924d6725c7222273"},{"code_id":"GK_RF_2","article_number":"978","version_date":"1994-11-30","article_text":"1. Если договор поручения прекращен до того, как поручение исполнено поверенным полностью, доверитель обязан возместить поверенному понесенные при исполнении поручения издержки, а когда поверенному причиталось вознаграждение, также уплатить ему вознаграждение соразмерно выполненной им работе. Это правило не применяется к исполнению поверенным поручения после того, как он узнал или должен был узнать о прекращении поручения.\n\n2. Отмена доверителем поручения не является основанием для возмещения убытков, причиненных поверенному прекращением договора поручения, за исключением случаев прекращения договора, предусматривающего действия поверенного в качестве коммерческого представителя.\n\n3. Отказ поверенного от исполнения поручения доверителя не является основанием для возмещения убытков, причиненных доверителю прекращением договора поручения, за исключением случаев отказа поверенного в условиях, когда доверитель лишен возможности иначе обеспечить свои интересы, а также отказа от исполнения договора, предусматривающего действия поверенного в качестве коммерческого представителя.","article_title":"Статья 978. Последствия прекращения договора поручения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9ad062215decdfcb67566e5023382aba7f075d722c54215480716bdc9c0db5d9"},{"code_id":"GK_RF_2","article_number":"979","version_date":"1994-11-30","article_text":"В случае смерти поверенного его наследники обязаны известить доверителя о прекращении договора поручения и принять меры, необходимые для охраны имущества доверителя, в частности сохранить его вещи и документы, и затем передать это имущество доверителю.\n\nТакая же обязанность лежит на ликвидаторе юридического лица, являющегося поверенным.","article_title":"Статья 979. Обязанности наследников поверенного и ликвидатора юридического лица, являющегося поверенным","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"af208ff3f26c65e7a8526eec8bd99b65777eec5a6237db0518dab0f86dd8b0a3"},{"code_id":"GK_RF_2","article_number":"980","version_date":"1994-11-30","article_text":"1. Действия без поручения, иного указания или заранее обещанного согласия заинтересованного лица в целях предотвращения вреда его личности или имуществу, исполнения его обязательства или в его иных непротивоправных интересах (действия в чужом интересе) должны совершаться исходя из очевидной выгоды или пользы и действительных или вероятных намерений заинтересованного лица и с необходимой по обстоятельствам дела заботливостью и осмотрительностью.\n\n2. Правила, предусмотренные настоящей главой, не применяются к действиям в интересе других лиц, совершаемым государственными и муниципальными органами, для которых такие действия являются одной из целей их деятельности.","article_title":"Статья 980. Условия действий в чужом интересе","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2e4a200a2f527096ea9c9cbd0f6ddff406594e63468dff4eeb304962f31bb1de"},{"code_id":"GK_RF_2","article_number":"981","version_date":"1994-11-30","article_text":"1. Лицо, действующее в чужом интересе, обязано при первой возможности сообщить об этом заинтересованному лицу и выждать в течение разумного срока его решения об одобрении или о неодобрении предпринятых действий, если только такое ожидание не повлечет серьезный ущерб для заинтересованного лица.\n\n2. Не требуется специально сообщать заинтересованному гражданину о действиях в его интересе, если эти действия предпринимаются в его присутствии.","article_title":"Статья 981. Уведомление заинтересованного лица о действиях в его интересе","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"062aa9a5e75047078f739c4c3327391649b11fb9cced2bbabddb57d1da56098c"},{"code_id":"GK_RF_2","article_number":"982","version_date":"1994-11-30","article_text":"Если лицо, в интересе которого предпринимаются действия без его поручения, одобрит эти действия, к отношениям сторон в дальнейшем применяются правила о договоре поручения или ином договоре, соответствующем характеру предпринятых действий, даже если одобрение было устным.","article_title":"Статья 982. Последствия одобрения заинтересованным лицом действий в его интересе","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1e5b7800143ddeff14247f05969cd26f46b455765d8d0baaf0d7be96e2c25851"},{"code_id":"GK_RF_2","article_number":"983","version_date":"1994-11-30","article_text":"1. Действия в чужом интересе, совершенные после того, как тому, кто их совершает, стало известно, что они не одобряются заинтересованным лицом, не влекут для последнего обязанностей ни в отношении совершившего эти действия, ни в отношении третьих лиц.\n\n2. Действия с целью предотвратить опасность для жизни лица, оказавшегося в опасности, допускаются и против воли этого лица, а исполнение обязанности по содержанию кого-либо - против воли того, на ком лежит эта обязанность.","article_title":"Статья 983. Последствия неодобрения заинтересованным лицом действий в его интересе","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7399a456f89b19c0c5c87bf7ffdc61753317dd9e8e41e7fa7835da8bd7cb2007"},{"code_id":"GK_RF_2","article_number":"984","version_date":"1994-11-30","article_text":"1. Необходимые расходы и иной реальный ущерб, понесенные лицом, действовавшим в чужом интересе в соответствии с правилами, предусмотренными настоящей главой, подлежат возмещению заинтересованным лицом, за исключением расходов, которые вызваны действиями, указанными в пункте 1 статьи 983 настоящего Кодекса.\n\nПраво на возмещение необходимых расходов и иного реального ущерба сохраняется и в том случае, когда действия в чужом интересе не привели к предполагаемому результату. Однако в случае предотвращения ущерба имуществу другого лица размер возмещения не должен превышать стоимость имущества.\n\n2. Расходы и иные убытки лица, действовавшего в чужом интересе, понесенные им в связи с действиями, которые предприняты после получения одобрения от заинтересованного лица (статья 982), возмещаются по правилам о договоре соответствующего вида.","article_title":"Статья 984. Возмещение убытков лицу, действовавшему в чужом интересе","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b31708fc2af77fa4540a980864b2022e161d1a2191d672a8d14fc0568d127d3b"},{"code_id":"GK_RF_2","article_number":"985","version_date":"1994-11-30","article_text":"Лицо, действия которого в чужом интересе привели к положительному для заинтересованного лица результату, имеет право на получение вознаграждения, если такое право предусмотрено законом, соглашением с заинтересованным лицом или обычаями делового оборота.","article_title":"Статья 985. Вознаграждение за действия в чужом интересе","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"dbb12f12314aac649cf8b8992f59aefd5a0dd2801e10efec74f78c084f7718aa"},{"code_id":"GK_RF_2","article_number":"986","version_date":"1994-11-30","article_text":"Обязанности по сделке, заключенной в чужом интересе, переходят к лицу, в интересах которого она совершена, при условии одобрения им этой сделки и если другая сторона не возражает против такого перехода либо при заключении сделки знала или должна была знать о том, что сделка заключена в чужом интересе.\n\nПри переходе обязанностей по такой сделке к лицу, в интересах которого она была заключена, последнему должны быть переданы и права по этой сделке.","article_title":"Статья 986. Последствия сделки в чужом интересе","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ff252d1bdd4f1eb46317ce6e84286413819a3f14987ae1ebe71622e69e8f04d7"},{"code_id":"GK_RF_2","article_number":"987","version_date":"1994-11-30","article_text":"Если действия, непосредственно не направленные на обеспечение интересов другого лица, в том числе в случае, когда совершившее их лицо ошибочно предполагало, что действует в своем интересе, привели к неосновательному обогащению другого лица, применяются правила, предусмотренные главой 60 настоящего Кодекса.","article_title":"Статья 987. Неосновательное обогащение вследствие действий в чужом интересе","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7c3b7265605c7a10f6d96f9bcfab860045d1402add28f3cd064bb4b858e32889"},{"code_id":"GK_RF_2","article_number":"988","version_date":"1994-11-30","article_text":"Отношения по возмещению вреда, причиненного действиями в чужом интересе заинтересованному лицу или третьим лицам, регулируются правилами, предусмотренными главой 59 настоящего Кодекса.","article_title":"Статья 988. Возмещение вреда, причиненного действиями в чужом интересе","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d79aee722bd3834f20cb97638c6d988c4369d4a97ce5835c2b0275425ffd0363"},{"code_id":"GK_RF_2","article_number":"989","version_date":"1994-11-30","article_text":"Лицо, действовавшее в чужом интересе, обязано представить лицу, в интересах которого осуществлялись такие действия, отчет с указанием полученных доходов и понесенных расходов и иных убытков.","article_title":"Статья 989. Отчет лица, действовавшего в чужом интересе","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7a712ebab81404db0eff6c0bdfc73a07e09ba96c40c114db680a81ed132eec8c"},{"code_id":"GK_RF_2","article_number":"990","version_date":"1994-11-30","article_text":"1. По договору комиссии одна сторона (комиссионер) обязуется по поручению другой стороны (комитента) за вознаграждение совершить одну или несколько сделок от своего имени, но за счет комитента.\n\nПо сделке, совершенной комиссионером с третьим лицом, приобретает права и становится обязанным комиссионер, хотя бы комитент и был назван в сделке или вступил с третьим лицом в непосредственные отношения по исполнению сделки.\n\n2. Договор комиссии может быть заключен на определенный срок или без указания срока его действия, с указанием или без указания территории его исполнения, с обязательством комитента не предоставлять третьим лицам право совершать в его интересах и за его счет сделки, совершение которых поручено комиссионеру, или без такого обязательства, с условиями или без условий относительно ассортимента товаров, являющихся предметом комиссии.\n\n3. Законом и иными правовыми актами могут быть предусмотрены особенности отдельных видов договора комиссии.","article_title":"Статья 990. Договор комиссии","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f5e480ec3cd5fc9c0e4e780b4ff05cf411d086195b42c37fd2029738dd5ea8b5"},{"code_id":"GK_RF_2","article_number":"991","version_date":"1994-11-30","article_text":"1. Комитент обязан уплатить комиссионеру вознаграждение, а в случае, когда комиссионер принял на себя ручательство за исполнение сделки третьим лицом (делькредере), также дополнительное вознаграждение в размере и в порядке, установленных в договоре комиссии.\n\nЕсли договором размер вознаграждения или порядок его уплаты не предусмотрен и размер вознаграждения не может быть определен исходя из условий договора, вознаграждение уплачивается после исполнения договора комиссии в размере, определяемом в соответствии с пунктом 3 статьи 424 настоящего Кодекса.\n\n2. Если договор комиссии не был исполнен по причинам, зависящим от комитента, комиссионер сохраняет право на комиссионное вознаграждение, а также на возмещение понесенных расходов.","article_title":"Статья 991. Комиссионное вознаграждение","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"24c59c884101e8ce45a9692a992153b9b68963ec1e9257f71d2a6b42ce58a03b"},{"code_id":"GK_RF_2","article_number":"992","version_date":"1994-11-30","article_text":"Принятое на себя поручение комиссионер обязан исполнить на наиболее выгодных для комитента условиях в соответствии с указаниями комитента, а при отсутствии в договоре комиссии таких указаний - в соответствии с обычаями делового оборота или иными обычно предъявляемыми требованиями.\n\nВ случае, когда комиссионер совершил сделку на условиях более выгодных, чем те, которые были указаны комитентом, дополнительная выгода делится между комитентом и комиссионером поровну, если иное не предусмотрено соглашением сторон.","article_title":"Статья 992. Исполнение комиссионного поручения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4809b1bb445afca6f77f6cfb39a3c3c9974cde5595cd89281572647a6f848c6f"},{"code_id":"GK_RF_2","article_number":"993","version_date":"1994-11-30","article_text":"1. Комиссионер не отвечает перед комитентом за неисполнение третьим лицом сделки, заключенной с ним за счет комитента, кроме случаев, когда комиссионер не проявил необходимой осмотрительности в выборе этого лица либо принял на себя ручательство за исполнение сделки (делькредере).\n\n2. В случае неисполнения третьим лицом сделки, заключенной с ним комиссионером, комиссионер обязан немедленно сообщить об этом комитенту, собрать необходимые доказательства, а также по требованию комитента передать ему права по такой сделке с соблюдением правил об уступке требования (статьи 382 - 386, 388, 389).\n\n3. Уступка прав комитенту по сделке на основании пункта 2 настоящей статьи допускается независимо от соглашения комиссионера с третьим лицом, запрещающего или ограничивающего такую уступку. Это не освобождает комиссионера от ответственности перед третьим лицом в связи с уступкой права в нарушение соглашения о ее запрете или об ограничении.","article_title":"Статья 993. Ответственность за неисполнение сделки, заключенной для комитента","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"76c8148f11aea29f078ab7f953db52f353fdb4312af9530decf3e1e5ede90528"},{"code_id":"GK_RF_2","article_number":"994","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено договором комиссии, комиссионер вправе в целях исполнения этого договора заключить договор субкомиссии с другим лицом, оставаясь ответственным за действия субкомиссионера перед комитентом.\n\nПо договору субкомиссии комиссионер приобретает в отношении субкомиссионера права и обязанности комитента.\n\n2. До прекращения договора комиссии комитент не вправе без согласия комиссионера вступать в непосредственные отношения с субкомиссионером, если иное не предусмотрено договором комиссии.","article_title":"Статья 994. Субкомиссия","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e3b27c3d1ad38c11a9ca0e80c60c15005662ed50fa5bce88bc5550fa0cd77694"},{"code_id":"GK_RF_2","article_number":"995","version_date":"1994-11-30","article_text":"1. Комиссионер вправе отступить от указаний комитента, если по обстоятельствам дела это необходимо в интересах комитента и комиссионер не мог предварительно запросить комитента либо не получил в разумный срок ответ на свой запрос. Комиссионер обязан уведомить комитента о допущенных отступлениях, как только уведомление стало возможным.\n\nКомиссионеру, действующему в качестве предпринимателя, может быть предоставлено комитентом право отступать от его указаний без предварительного запроса. В этом случае комиссионер обязан в разумный срок уведомить комитента о допущенных отступлениях, если иное не предусмотрено договором комиссии.\n\n2. Комиссионер, продавший имущество по цене ниже согласованной с комитентом, обязан возместить последнему разницу, если не докажет, что у него не было возможности продать имущество по согласованной цене и продажа по более низкой цене предупредила еще большие убытки. В случае, когда комиссионер был обязан предварительно запросить комитента, комиссионер должен также доказать, что он не имел возможности получить предварительно согласие комитента на отступление от его указаний.\n\n3. Если комиссионер купил имущество по цене выше согласованной с комитентом, комитент, не желающий принять такую покупку, обязан заявить об этом комиссионеру в разумный срок по получении от него извещения о заключении сделки с третьим лицом. В противном случае покупка признается принятой комитентом.\n\nЕсли комиссионер сообщил, что принимает разницу в цене на свой счет, комитент не вправе отказаться от заключенной для него сделки.","article_title":"Статья 995. Отступление от указаний комитента","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ba50e50963e2117a1d12fea3effc727188145a30a076b6ddc7ae680844f5b9aa"},{"code_id":"GK_RF_2","article_number":"996","version_date":"1994-11-30","article_text":"1. Вещи, поступившие к комиссионеру от комитента либо приобретенные комиссионером за счет комитента, являются собственностью последнего.\n\n2. Комиссионер вправе в соответствии со статьей 359 настоящего Кодекса удерживать находящиеся у него вещи, которые подлежат передаче комитенту либо лицу, указанному комитентом, в обеспечение своих требований по договору комиссии.\n\nВ случае объявления комитента несостоятельным (банкротом) указанное право комиссионера прекращается, а его требования к комитенту в пределах стоимости вещей, которые он удерживал, удовлетворяются в соответствии со статьей 360 настоящего Кодекса наравне с требованиями, обеспеченными залогом.","article_title":"Статья 996. Права на вещи, являющиеся предметом комиссии","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a466ecf5cf36f7c056fe8e683a285d144bc1376bb62eef7332b2b2d96fd9e55e"},{"code_id":"GK_RF_2","article_number":"997","version_date":"1994-11-30","article_text":"Комиссионер вправе в соответствии со статьей 410 настоящего Кодекса удержать причитающиеся ему по договору комиссии суммы из всех сумм, поступивших к нему за счет комитента. Однако кредиторы комитента, пользующиеся в отношении очередности удовлетворения их требований преимуществом перед залогодержателями, не лишаются права на удовлетворение этих требований из удержанных комиссионером сумм.","article_title":"Статья 997. Удовлетворение требований комиссионера из причитающихся комитенту сумм","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"621a6c462b72c35a3e5327aeceed90ea2ef37c36588b8e550e53748099266683"},{"code_id":"GK_RF_2","article_number":"998","version_date":"1994-11-30","article_text":"1. Комиссионер отвечает перед комитентом за утрату, недостачу или повреждение находящегося у него имущества комитента.\n\n2. Если при приеме комиссионером имущества, присланного комитентом либо поступившего к комиссионеру для комитента, в этом имуществе окажутся повреждения или недостача, которые могут быть замечены при наружном осмотре, а также в случае причинения кем-либо ущерба имуществу комитента, находящемуся у комиссионера, комиссионер обязан принять меры по охране прав комитента, собрать необходимые доказательства и обо всем без промедления сообщить комитенту.\n\n3. Комиссионер, не застраховавший находящееся у него имущество комитента, отвечает за это лишь в случаях, когда комитент предписал ему застраховать имущество за счет комитента либо страхование этого имущества комиссионером предусмотрено договором комиссии или обычаями делового оборота.","article_title":"Статья 998. Ответственность комиссионера за утрату, недостачу или повреждение имущества комитента","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"36a0bc0cc8973fb0420cf8c1ed8e6e908143f3703624ff039caa129b92d163fd"},{"code_id":"GK_RF_2","article_number":"999","version_date":"1994-11-30","article_text":"По исполнении поручения комиссионер обязан представить комитенту отчет и передать ему все полученное по договору комиссии. Комитент, имеющий возражения по отчету, должен сообщить о них комиссионеру в течение тридцати дней со дня получения отчета, если соглашением сторон не установлен иной срок. В противном случае отчет при отсутствии иного соглашения считается принятым.","article_title":"Статья 999. Отчет комиссионера","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c03c84e7d1ac0be04b8a1ccde56c226a2c576018fbf0f65e191cd196a7bb44e2"},{"code_id":"KoAP_RF","article_number":"1.1","version_date":"2001-12-30","article_text":"1. Законодательство об административных правонарушениях состоит из настоящего Кодекса и принимаемых в соответствии с ним законов субъектов Российской Федерации об административных правонарушениях.\n\n2. Настоящий Кодекс основывается на Конституции Российской Федерации, общепризнанных принципах и нормах международного права и международных договорах Российской Федерации. Если международным договором Российской Федерации установлены иные правила, чем предусмотренные законодательством об административных правонарушениях, то применяются правила международного договора.","article_title":"Статья 1.1. Законодательство об административных правонарушениях","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"29b00c1e484c1e52818132a0c4787f637ae84dcb3e1fb1a197ceb33f37202a1a"},{"code_id":"KoAP_RF","article_number":"1.2","version_date":"2001-12-30","article_text":"Задачами законодательства об административных правонарушениях являются защита личности, охрана прав и свобод человека и гражданина, охрана здоровья граждан, санитарно-эпидемиологического благополучия населения, защита общественной нравственности, охрана окружающей среды, установленного порядка осуществления государственной власти, общественного порядка и общественной безопасности, собственности, защита законных экономических интересов физических и юридических лиц, общества и государства от административных правонарушений, а также предупреждение административных правонарушений.","article_title":"Статья 1.2. Задачи законодательства об административных правонарушениях","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"77f6c66a992d183890c99e19af72c9590d5bfc45e3af4fe182bfbe10b063c80c"},{"code_id":"KoAP_RF","article_number":"1.3","version_date":"2001-12-30","article_text":"1. К ведению Российской Федерации в области законодательства об административных правонарушениях относится установление:\n\n1) общих положений и принципов законодательства об административных правонарушениях;\n\n2) перечня видов административных наказаний и правил их применения;\n\n3) административной ответственности по вопросам, имеющим федеральное значение, в том числе административной ответственности за нарушение правил и норм, предусмотренных федеральными законами и иными нормативными правовыми актами Российской Федерации;\n\n31) административной ответственности за нарушение правил и норм, предусмотренных нормативными правовыми актами органов публичной власти федеральной территории, устанавливающими особенности регулирования отдельных отношений в федеральной территории в сферах, определенных федеральными законами и иными нормативными правовыми актами Российской Федерации, либо предусмотренных нормативными правовыми актами органов публичной власти федеральной территории, принятыми в рамках осуществления полномочий, переданных им Российской Федерацией; (Дополнение пунктом - Федеральный закон от 08.08.2024 № 245-ФЗ)\n\n4) порядка производства по делам об административных правонарушениях, в том числе установление мер обеспечения производства по делам об административных правонарушениях;\n\n5) порядка исполнения постановлений о назначении административных наказаний.\n\n2. В соответствии с законодательством о судебной системе настоящий Кодекс определяет подсудность дел об административных правонарушениях судам.\n\n3. В соответствии с законодательством о защите прав несовершеннолетних настоящий Кодекс определяет подведомственность дел об административных правонарушениях комиссиям по делам несовершеннолетних и защите их прав.\n\n4. В соответствии с установленной структурой федеральных органов исполнительной власти настоящий Кодекс определяет подведомственность дел об административных правонарушениях, предусмотренных настоящим Кодексом, федеральным органам исполнительной власти.","article_title":"Статья 1.3. Предметы ведения Российской Федерации в области законодательства об административных правонарушениях","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bb56c34c88c0846838362927eb114475656b7da467088114577f86e16a0fa244"},{"code_id":"KoAP_RF","article_number":"1.31","version_date":"2001-12-30","article_text":"1. К ведению субъектов Российской Федерации в области законодательства об административных правонарушениях относится:\n\n1) установление законами субъектов Российской Федерации об административных правонарушениях административной ответственности за нарушение законов и иных нормативных правовых актов субъектов Российской Федерации, нормативных правовых актов органов местного самоуправления;\n\n11) установление законами Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области об административных правонарушениях административной ответственности за завышение цен (тарифов) на товары и (или) предельных уровней таких цен (тарифов), установленных нормативными правовыми актами данных субъектов Российской Федерации с учетом особенностей, предусмотренных федеральными конституционными законами; (Дополнение пунктом - Федеральный закон от 12.12.2023 № 574-ФЗ)\n\n12) установление законами субъектов Российской Федерации об административных правонарушениях административной ответственности за нарушение правил и норм, предусмотренных нормативными правовыми актами органов публичной власти федеральной территории, за исключением случаев, предусмотренных пунктом 31 части 1 статьи 1.3 настоящего Кодекса; (Дополнение пунктом - Федеральный закон от 08.08.2024 № 245-ФЗ)\n\n2) организация производства по делам об административных правонарушениях, предусмотренных законами субъектов Российской Федерации;\n\n3) определение подведомственности дел об административных правонарушениях, предусмотренных законами субъектов Российской Федерации, в соответствии с частью 2 статьи 22.1 настоящего Кодекса;\n\n4) создание комиссий по делам несовершеннолетних и защите их прав;\n\n5) создание административных комиссий, иных коллегиальных органов в целях привлечения к административной ответственности, предусмотренной законами субъектов Российской Федерации;\n\n6) определение перечня должностных лиц, уполномоченных составлять протоколы об административных правонарушениях, предусмотренных законами субъектов Российской Федерации;\n\n61) определение перечней должностных лиц, уполномоченных составлять протоколы об административных правонарушениях, предусмотренных настоящим Кодексом, в случаях, предусмотренных статьей 28.3 настоящего Кодекса; (Дополнение пунктом - Федеральный закон от 14.10.2014 № 307-ФЗ)\n\n7) регулирование законами субъектов Российской Федерации иных вопросов в соответствии с настоящим Кодексом.\n\n2. Законами субъектов Российской Федерации органы местного самоуправления могут наделяться отдельными полномочиями субъекта Российской Федерации по решению вопросов, указанных в пунктах 4 - 6 части 1 настоящей статьи, с передачей необходимых для их осуществления материальных и финансовых средств. В случае наделения органа местного самоуправления указанными полномочиями его должностные лица вправе составлять протоколы об административных правонарушениях, предусмотренных законами субъекта Российской Федерации.\n\n3. В случаях, предусмотренных законами субъектов Российской Федерации, должностные лица органов местного самоуправления вправе составлять протоколы об административных правонарушениях, предусмотренных настоящим Кодексом или законами субъектов Российской Федерации, при осуществлении органами местного самоуправления полномочий по контролю (надзору), делегированных Российской Федерацией или субъектами Российской Федерации, а также при осуществлении муниципального контроля.\n\n4. Органы исполнительной власти субъектов Российской Федерации в пределах компетенции, установленной главой 23 настоящего Кодекса, уполномочены рассматривать дела об административных правонарушениях, предусмотренных настоящим Кодексом.\n\n5. Должностные лица органов исполнительной власти субъектов Российской Федерации в пределах компетенции соответствующего органа исполнительной власти субъекта Российской Федерации уполномочены составлять протоколы об административных правонарушениях, предусмотренных настоящим Кодексом, в случаях, указанных в статье 28.3 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 28.12.2009 № 380-ФЗ)","article_title":"Статья 1.31. Предметы ведения субъектов Российской Федерации в области законодательства об административных правонарушениях","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9303d7c210fd92d42d054c8a0088b0cf87f86b85811d6e57cd92f620964f2d82"},{"code_id":"KoAP_RF","article_number":"1.4","version_date":"2001-12-30","article_text":"1. Лица, совершившие административные правонарушения, равны перед законом. Физические лица подлежат административной ответственности независимо от пола, расы, национальности, языка, происхождения, имущественного и должностного положения, места жительства, отношения к религии, убеждений, принадлежности к общественным объединениям, а также других обстоятельств. Юридические лица подлежат административной ответственности независимо от места нахождения, организационно-правовых форм, подчиненности, а также других обстоятельств.","article_title":"Статья 1.4. Принцип равенства перед законом","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b4c587e3d0ffe133607a5f43744332bd1b47c7461feee3df431c5bf480cfc22c"},{"code_id":"KoAP_RF","article_number":"1.5","version_date":"2001-12-30","article_text":"1. Лицо подлежит административной ответственности только за те административные правонарушения, в отношении которых установлена его вина.\n\n2. Лицо, в отношении которого ведется производство по делу об административном правонарушении, считается невиновным, пока его вина не будет доказана в порядке, предусмотренном настоящим Кодексом, и установлена вступившим в законную силу постановлением судьи, органа, должностного лица, рассмотревших дело.\n\nПримечание. Положение части 3 настоящей статьи не распространяется на административные правонарушения, предусмотренные частями 31 - 34 статьи 8.2, главой 12 настоящего Кодекса, и административные правонарушения в области благоустройства территории, административные правонарушения, выразившиеся в несоблюдении порядка внесения платы за проезд транспортного средства по платным автомобильным дорогам общего пользования регионального, межмуниципального и местного значения, частным автомобильным дорогам общего пользования, платным участкам автомобильных дорог общего пользования регионального, межмуниципального и местного значения, частных автомобильных дорог общего пользования, предусмотренные законами субъектов Российской Федерации, совершенные с использованием транспортных средств либо собственником, владельцем земельного участка либо другого объекта недвижимости, в случае фиксации этих административных правонарушений работающими в автоматическом режиме специальными техническими средствами, имеющими функции фото- и киносъемки, видеозаписи, или средствами фото- и киносъемки, видеозаписи. (Дополнение примечанием - Федеральный закон от 24.07.2007 № 210-ФЗ) (В редакции  федеральных законов от 21.04.2011 № 69-ФЗ, от 28.07.2012 № 133-ФЗ, от 14.07.2022 № 287-ФЗ, от 31.07.2023 № 405-ФЗ)","article_title":"Статья 1.5. Презумпция невиновности","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"dca0f27b28bfbbcbc4e5a79ab6711469dc82fd32dbfe3514943873a02c6d362c"},{"code_id":"KoAP_RF","article_number":"1.6","version_date":"2001-12-30","article_text":"1. Лицо, привлекаемое к административной ответственности, не может быть подвергнуто административному наказанию и мерам обеспечения производства по делу об административном правонарушении иначе как на основаниях и в порядке, установленных законом.\n\n2. Применение уполномоченными на то органом или должностным лицом административного наказания и мер обеспечения производства по делу об административном правонарушении в связи с административным правонарушением осуществляется в пределах компетенции указанных органа или должностного лица в соответствии с законом.\n\n3. При применении мер административного принуждения не допускаются решения и действия (бездействие), унижающие человеческое достоинство.","article_title":"Статья 1.6. Обеспечение законности при применении мер административного принуждения в связи с административным правонарушением","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1472dc5981df9fe8e7809d126a1ad2b197bc52fae4cd66bece47859a532a93c8"},{"code_id":"KoAP_RF","article_number":"1.7","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 24.07.2007 № 210-ФЗ)","article_title":"Статья 1.7. Действие законодательства об административных правонарушениях во времени","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9c39514bd15da8ebee51e7f0a91ebb27fc8a81e0775cfd3ef8857a884ffdd993"},{"code_id":"KoAP_RF","article_number":"1.8","version_date":"2001-12-30","article_text":"(Дополнение статьей - Федеральный закон от 24.07.2007 № 210-ФЗ)\n\nГЛАВА 2. АДМИНИСТРАТИВНОЕ ПРАВОНАРУШЕНИЕ И АДМИНИСТРАТИВНАЯ ОТВЕТСТВЕННОСТЬ","article_title":"Статья 1.8. Действие законодательства об административных правонарушениях в пространстве","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"94c97fe8b54d05527a7ccbe052d1dac6215f6abdf282ece465907f964580fb3b"},{"code_id":"KoAP_RF","article_number":"2.1","version_date":"2001-12-30","article_text":"1. Административным правонарушением признается противоправное, виновное действие (бездействие) физического или юридического лица, за которое настоящим Кодексом или законами субъектов Российской Федерации об административных правонарушениях установлена административная ответственность.\n\n2. Юридическое лицо признается виновным в совершении административного правонарушения, если будет установлено, что у него имелась возможность для соблюдения правил и норм, за нарушение которых настоящим Кодексом или законами субъекта Российской Федерации предусмотрена административная ответственность, но данным лицом не были приняты все зависящие от него меры по их соблюдению.\n\n3. Назначение административного наказания юридическому лицу не освобождает от административной ответственности за данное правонарушение виновное физическое лицо, равно как и привлечение к административной или уголовной ответственности физического лица не освобождает от административной ответственности за данное правонарушение юридическое лицо, за исключением случаев, предусмотренных частями\n\n4 и 5 настоящей статьи. (В редакции Федерального закона от 26.03.2022 № 70-ФЗ)","article_title":"Статья 2.1. Административное правонарушение","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"81d91484730ae78fbe2ed7a75855399449e5c92289fddbc1118b4545825cd558"},{"code_id":"KoAP_RF","article_number":"2.10","version_date":"2001-12-30","article_text":"1. Юридические лица подлежат административной ответственности за совершение административных правонарушений в случаях, предусмотренных статьями раздела II настоящего Кодекса или законами субъектов Российской Федерации об административных правонарушениях.\n\n2. В случае, если в статьях разделов I, III, IV, V настоящего Кодекса не указано, что установленные данными статьями нормы применяются только к физическому лицу или только к юридическому лицу, данные нормы в равной мере действуют в отношении и физического, и юридического лица, за исключением случаев, если по смыслу данные нормы относятся и могут быть применены только к физическому лицу.\n\n3. При слиянии нескольких юридических лиц к административной ответственности за совершение административного правонарушения привлекается вновь возникшее юридическое лицо.\n\n4. При присоединении юридического лица к другому юридическому лицу к административной ответственности за совершение административного правонарушения привлекается присоединившее юридическое лицо.\n\n5. При разделении юридического лица или при выделении из состава юридического лица одного или нескольких юридических лиц к административной ответственности за совершение административного правонарушения привлекается то юридическое лицо, к которому согласно разделительному балансу перешли права и обязанности по заключенным сделкам или имуществу, в связи с которыми было совершено административное правонарушение.\n\n6. При преобразовании юридического лица одного вида в юридическое лицо другого вида к административной ответственности за совершение административного правонарушения привлекается вновь возникшее юридическое лицо.\n\n7. В случаях, указанных в частях 3 - 6 настоящей статьи, административная ответственность за совершение административного правонарушения наступает независимо от того, было ли известно привлекаемому к административной ответственности юридическому лицу о факте административного правонарушения до завершения реорганизации.\n\n8. Административные наказания, назначенные в соответствии с пунктами 2 - 4 части 1 статьи 3.2 настоящего Кодекса юридическому лицу за совершение административного правонарушения до завершения реорг\n\nанизации юридического лица, применяются с учетом положений частей 3 - 6 настоящей статьи.\n\nГЛАВА 3. АДМИНИСТРАТИВНОЕ НАКАЗАНИЕ","article_title":"Статья 2.10. Административная ответственность юридических лиц","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"072a926de1e4a6fdaf73e54f5b7296e9d58c19d38a662e9d06bcd5409c70aab4"},{"code_id":"KoAP_RF","article_number":"2.2","version_date":"2001-12-30","article_text":"1. Административное правонарушение признается совершенным умышленно, если лицо, его совершившее, сознавало противоправный характер своего действия (бездействия), предвидело его вредные последствия и желало наступления таких последствий или сознательно их допускало либо относилось к ним безразлично.\n\n2. Административное правонарушение признается совершенным по неосторожности, если лицо, его совершившее, предвидело возможность наступления вредных последствий своего действия (бездействия), но без достаточных к тому оснований самонадеянно рассчитывало на предотвращение таких последствий либо не предвидело возможности наступления таких последствий, хотя должно было и могло их предвидеть.","article_title":"Статья 2.2. Формы вины","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0bb955f789c95e5320d7b5c7a63bd674a4bd89e47ae01c1c2ce58bcba3064f69"},{"code_id":"KoAP_RF","article_number":"2.3","version_date":"2001-12-30","article_text":"1. Административной ответственности подлежит лицо, достигшее к моменту совершения административного правонарушения возраста шестнадцати лет.\n\n2. С учетом конкретных обстоятельств дела и данных о лице, совершившем административное правонарушение в возрасте от шестнадцати до восемнадцати лет, комиссией по делам несовершеннолетних и защите их прав указанное лицо может быть освобождено от административной ответственности с применением к нему меры воздействия, предусмотренной федеральным законодательством о защите прав несовершеннолетних.","article_title":"Статья 2.3. Возраст, по достижении которого наступает административная ответственность","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"85bd63d5826e558bd74bfdbd0ff8821a97eb322acc1ab837379758344fd33a04"},{"code_id":"KoAP_RF","article_number":"2.4","version_date":"2001-12-30","article_text":"Административной ответственности подлежит должностное лицо в случае совершения им административного правонарушения в связи с неисполнением либо ненадлежащим исполнением своих служебных обязанностей.","article_title":"Статья 2.4. Административная ответственность должностных лиц","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"22b9613e6482fec54192d3cf204b8d62d55bb8017f330ca182121be3abe1cc50"},{"code_id":"KoAP_RF","article_number":"2.5","version_date":"2001-12-30","article_text":"(Статья в редакции Федерального закона от 04.12.2006 № 203-ФЗ)","article_title":"Статья 2.5. Административная ответственность военнослужащих, граждан, призванных на военные сборы, и лиц, имеющих специальные звания","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7b12d902da61e83c41f3b236768e6d01083f60d730068a1f5bd5576a8450778d"}]$law7d0039$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
